{
    *ppszResolvedPath = 0;
    LPITEMIDLIST pidlFolder = SHSimpleIDListFromPath(pszFolderPath);
    HRESULT hr = pidlFolder ? ((HRESULT)0L) : ((HRESULT)0x80070057L);
    if ((((HRESULT)(hr)) >= 0))
    {
        IShellItem *psiFolder;
        hr = SHCreateItemFromIDList(pidlFolder, __uuidof(**(&psiFolder)), IID_PPV_ARGS_Helper(&psiFolder));
        if ((((HRESULT)(hr)) >= 0))
        {
            IShellItem *psiResolved;
            hr = plib->ResolveFolder(psiFolder, dwTimeout, __uuidof(**(&psiResolved)), IID_PPV_ARGS_Helper(&psiResolved));
            if ((((HRESULT)(hr)) >= 0))
            {
                hr = psiResolved->GetDisplayName(SIGDN_DESKTOPABSOLUTEPARSING, ppszResolvedPath);
                psiResolved->Release();
            }
            psiFolder->Release();
        }
        CoTaskMemFree(pidlFolder);
    }
    return hr;
}

