template <class Traits, class Verifier>
class GenericScopedHandle {
 public:
  using Handle = typename Traits::Handle;

  GenericScopedHandle() : handle_(Traits::NullHandle()) {}

  explicit GenericScopedHandle(Handle handle) : handle_(Traits::NullHandle()) {
    Set(handle);
  }

  GenericScopedHandle(GenericScopedHandle&& other)
      : handle_(Traits::NullHandle()) {
    Set(other.Take());
  }

  GenericScopedHandle(const GenericScopedHandle&) = delete;
  GenericScopedHandle& operator=(const GenericScopedHandle&) = delete;

  ~GenericScopedHandle() { Close(); }

  bool is_valid() const { return Traits::IsHandleValid(handle_); }


  bool IsValid() const { return is_valid(); }

  GenericScopedHandle& operator=(GenericScopedHandle&& other) {
    true ? (void)0 : ::logging::VoidifyStream((::logging::CheckOpValueStr(this), ::logging::CheckOpValueStr(&other), (this)!=(&other))) & (*::logging::g_swallow_stream);
    Set(other.Take());
    return *this;
  }

  void Set(Handle handle) {
    if (handle_ != handle) {

      auto last_error = ::GetLastError();
      Close();

      if (Traits::IsHandleValid(handle)) {
        handle_ = handle;
        Verifier::StartTracking(handle, this, _ReturnAddress(),
                                GetProgramCounter());
      }
      ::SetLastError(last_error);
    }
  }

  Handle get() const { return handle_; }


  Handle Get() const { return get(); }


  [[nodiscard]] Handle release() {
    Handle temp = handle_;
    handle_ = Traits::NullHandle();
    if (Traits::IsHandleValid(temp)) {
      Verifier::StopTracking(temp, this, _ReturnAddress(),
                             GetProgramCounter());
    }
    return temp;
  }


  [[nodiscard]] Handle Take() { return release(); }


  void Close() {
    if (Traits::IsHandleValid(handle_)) {
      Verifier::StopTracking(handle_, this, _ReturnAddress(),
                             GetProgramCounter());

      Traits::CloseHandle(handle_);
      handle_ = Traits::NullHandle();
    }
  }

 private:
  friend class ScopedHandleDeathTest_HandleVerifierWrongOwner_Test; friend class ScopedHandleDeathTest_DISABLED_HandleVerifierWrongOwner_Test; friend class ScopedHandleDeathTest_FLAKY_HandleVerifierWrongOwner_Test;
  friend class ScopedHandleDeathTest_HandleVerifierUntrackedHandle_Test; friend class ScopedHandleDeathTest_DISABLED_HandleVerifierUntrackedHandle_Test; friend class ScopedHandleDeathTest_FLAKY_HandleVerifierUntrackedHandle_Test;

  Handle handle_;
};




